fn parse_age(input: Str) -> Result[Int, Str] {
  // simplified: only accepts "25"
  if input == "25" { return Ok(25); }
  return Err("Invalid age");
}

fn check_voting_age(age: Int) -> Result[Str, Str] {
  if age < 0 || age > 120 { return Err("Invalid age range"); }
  if age >= 18 { return Ok("Eligible"); }
  return Err("Too young");
}

fn main() -> Int {
  match parse_age("25") {
    Ok(age) => {
      match check_voting_age(age) {
        Ok(_) => { return 1; }
        Err(_) => { return 0; }
      }
    }
    Err(_) => { return 0; }
  }
}
